import 'package:udara_cli/core/core.dart';import 'package:udara_cli/services/config_service.dart';class ConfigCommand extends UdaraCommand {  @override  final String name = 'config';  @override  final String description = 'View current CLI configuration settings.';  @override  Future<void> run() async {    await ConfigService.showConfig();    print('\n💡 Tips:');    print('• Run "udara_cli setup" to modify these settings');    print('• Use --slack-channel parameter in build command to specify channel');    print('• Run "udara_cli setup --reset" to reset all settings');  }}